import{_ as t,o,c as i,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2016-JAN-26 -- Ceph Tech Talks: High-Performance Production Databases on Ceph","description":"","frontmatter":{"title":"2016-JAN-26 -- Ceph Tech Talks: High-Performance Production Databases on Ceph","date":"2016-01-28T00:00:00.000Z","updated":"2016-01-29T00:00:00.000Z","tags":["Ceph","分布式存储","高性能数据库","容器化","自动化部署"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2016/2016-JAN-26_--_Ceph_Tech_Talks_-_High-Performance_Production_Databases_on_Ceph.md","filePath":"posts/2016/2016-JAN-26_--_Ceph_Tech_Talks_-_High-Performance_Production_Databases_on_Ceph.md","lastUpdated":1780459816000}'),e={name:"posts/2016/2016-JAN-26_--_Ceph_Tech_Talks_-_High-Performance_Production_Databases_on_Ceph.md"};function r(n,l,a,_,p,g){return o(),i("div",null,[...l[0]||(l[0]=[s("<p><strong>会议纪要</strong></p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 未知</p><p><strong>会议主题</strong>： 高性能数据库在Ceph上的运行实践</p><p><strong>会议内容</strong>：</p><ul><li><strong>公司背景</strong>： Medallia公司自2010年起，从70名员工发展到700名，致力于为全球客户提供实时数据分析服务。</li><li><strong>问题与挑战</strong>： <ul><li>现有数据库部署在数百台服务器上，服务器配置分散，缺乏统一管理。</li><li>数据库服务器维护成本高，升级风险大。</li><li>需要构建一个可扩展、高可用、高性能的数据库平台。</li></ul></li><li><strong>解决方案</strong>： <ul><li>采用Ceph作为存储层，实现数据存储的可靠性和可扩展性。</li><li>使用Docker进行容器化部署，简化运维流程。</li><li>利用OpenStack进行资源调度和自动化部署。</li><li>实现网络自动化，降低网络故障风险。</li></ul></li><li><strong>关键技术</strong>： <ul><li><strong>Ceph</strong>： 作为分布式存储系统，提供高可用、可扩展的存储服务。</li><li><strong>Docker</strong>： 实现应用容器化，简化部署和运维。</li><li><strong>OpenStack</strong>： 实现资源管理和自动化部署。</li><li><strong>OSPF</strong>： 实现网络自动化和IP地址管理。</li><li><strong>Flocker</strong>： 实现容器存储的持久化和迁移。</li></ul></li><li><strong>性能测试</strong>： <ul><li>网络延迟：约5微秒。</li><li>单流TCP性能：22或38 Gbps。</li><li>多流TCP性能：接近40 Gbps。</li><li>单流I/O性能：550 MB/s。</li><li>多流I/O性能：接近4 GB/s。</li></ul></li><li><strong>未来计划</strong>： <ul><li>推出基于Ceph的数据库容器化解决方案。</li><li>优化性能，降低延迟。</li><li>推广开源技术。</li></ul></li></ul><p><strong>行动计划</strong>：</p><ul><li>完成基于Ceph的数据库容器化解决方案。</li><li>优化性能，降低延迟。</li><li>推广开源技术。</li></ul><p><strong>会议总结</strong>：</p><p>Medallia公司通过采用Ceph、Docker、OpenStack等开源技术，成功构建了一个高性能、高可用的数据库平台。该平台具有以下特点：</p><ul><li><strong>高可用</strong>： 数据存储在Ceph集群中，实现数据冗余和故障转移。</li><li><strong>可扩展</strong>： 可根据需求动态添加节点，提高性能和容量。</li><li><strong>高性能</strong>： 网络延迟低，I/O性能高。</li><li><strong>易于运维</strong>： 自动化部署和运维，降低运维成本。</li></ul><p>该方案为其他企业构建高性能数据库平台提供了参考。</p>",12)])])}const u=t(e,[["render",r]]);export{h as __pageData,u as default};
